changeSet.sql:
DROP TABLE trades;

CREATE SEQUENCE trades_id_seq;

CREATE TABLE trades (
    id              BIGINT NOT NULL DEFAULT nextval('trades_id_seq'),
    trade_ref       VARCHAR(30) NOT NULL,
    instrument_id   BIGINT NOT NULL,
    counterparty_id BIGINT NOT NULL,
    asset_class     VARCHAR(20) NOT NULL,
    side            VARCHAR(4) NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE NOT NULL,
    status          VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    modified_at     TIMESTAMP,
    CONSTRAINT pk_trades PRIMARY KEY (id, trade_date),
    CONSTRAINT uq_trades_trade_ref UNIQUE (trade_ref, trade_date),
    CONSTRAINT fk_trades_instrument FOREIGN KEY (instrument_id)
        REFERENCES instruments(id),
    CONSTRAINT fk_trades_counterparty FOREIGN KEY (counterparty_id)
        REFERENCES counterparties(id)
) PARTITION BY RANGE (trade_date);

ALTER SEQUENCE trades_id_seq OWNED BY trades.id;

CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);

CREATE TABLE trades_y2026m04 PARTITION OF trades
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_y2026m05 PARTITION OF trades
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_y2026m06 PARTITION OF trades
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_y2026m07 PARTITION OF trades
    FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE trades_default PARTITION OF trades DEFAULT;

rollback.sql:
DROP TABLE IF EXISTS trades_default;
DROP TABLE IF EXISTS trades_y2026m07;
DROP TABLE IF EXISTS trades_y2026m06;
DROP TABLE IF EXISTS trades_y2026m05;
DROP TABLE IF EXISTS trades_y2026m04;
DROP TABLE IF EXISTS trades;
DROP SEQUENCE IF EXISTS trades_id_seq;

CREATE TABLE trades (
    id              BIGSERIAL PRIMARY KEY,
    trade_ref       VARCHAR(30) NOT NULL UNIQUE,
    instrument_id   BIGINT NOT NULL REFERENCES instruments(id),
    counterparty_id BIGINT NOT NULL REFERENCES counterparties(id),
    asset_class     VARCHAR(20) NOT NULL,
    side            VARCHAR(4) NOT NULL,
    quantity        NUMERIC(18,4) NOT NULL,
    price           NUMERIC(18,4) NOT NULL,
    trade_date      DATE NOT NULL,
    status          VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    deleted_at      TIMESTAMP,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    modified_at     TIMESTAMP
);
CREATE INDEX idx_trades_trade_date ON trades (trade_date);
CREATE INDEX idx_trades_status ON trades (status);
